// Built-in click and typing sound effects (generated by scripts/make-sounds.py).
// Shared by the editor preview and by export so both place them identically.

export const CLICK_STYLES = [["soft", "Soft"], ["crisp", "Crisp"], ["classic", "Classic"]];
export const KEY_STYLES = [["mechanical", "Mechanical"], ["soft", "Soft"], ["thock", "Thock"]];

const cache = new Map(); // `${ctxId}|${name}` -> Promise<AudioBuffer|null>
let ctxCounter = 0;
const ctxIds = new WeakMap();
const idOf = (ctx) => {
  if (!ctxIds.has(ctx)) ctxIds.set(ctx, ++ctxCounter);
  return ctxIds.get(ctx);
};

function load(ctx, name) {
  const key = `${idOf(ctx)}|${name}`;
  if (!cache.has(key)) {
    cache.set(
      key,
      fetch(`sounds/${name}.wav`)
        .then((r) => r.arrayBuffer())
        .then((b) => ctx.decodeAudioData(b))
        .catch(() => null),
    );
  }
  return cache.get(key);
}

/** Decode one sound set: { normal: AudioBuffer[], space, enter }. */
export async function loadSet(ctx, kind, style) {
  if (kind === "click") {
    const normal = (await Promise.all([0, 1, 2].map((i) => load(ctx, `click-${style}-${i}`)))).filter(Boolean);
    return { normal };
  }
  const normal = (await Promise.all([0, 1, 2, 3, 4].map((i) => load(ctx, `key-${style}-${i}`)))).filter(Boolean);
  const [space, enter] = await Promise.all([load(ctx, `key-${style}-space`), load(ctx, `key-${style}-enter`)]);
  return { normal, space: space || normal[0], enter: enter || normal[0] };
}

// Deterministic "randomness" from the event time, so preview and export agree.
const hash = (t) => (Math.imul(Math.round(t * 10) | 0, 2654435761) >>> 0) / 4294967296;

/**
 * Schedule the effect hits of `marks` ([{tOutMs, kind?}]) that fall in [fromMs, toMs).
 * `when(tOutMs)` returns the AudioContext time for an output time.
 */
export function scheduleMarks(ctx, dest, marks, set, fromMs, toMs, when, gainOf = 1) {
  if (!set || !set.normal?.length) return [];
  const nodes = [];
  for (const m of marks) {
    const t = m.tOutMs;
    if (t < fromMs || t >= toMs) continue;
    const h = hash(t);
    let buf = set.normal[Math.floor(h * set.normal.length) % set.normal.length];
    if (m.kind === 1 && set.space) buf = set.space;
    else if (m.kind === 2 && set.enter) buf = set.enter;
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.playbackRate.value = 0.96 + h * 0.08;
    const g = ctx.createGain();
    g.gain.value = (0.82 + hash(t + 17) * 0.18) * gainOf;
    src.connect(g).connect(dest);
    src.start(Math.max(ctx.currentTime, when(t)));
    nodes.push(src);
  }
  return nodes;
}
